<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { ArrowRight, Pencil } from 'lucide-vue-next'
import { useEmployeesQuery } from '@/modules/employees/queries/useEmployeesQuery'
import { useOrganizationUnitsFlatQuery } from '@/modules/organization/queries/useOrganizationUnitsQuery'
import type { AppSelectOption } from '@/shared/components/AppSelect.vue'
import PermissionGuard from '@/shared/components/PermissionGuard.vue'
import { usePermissions } from '@/shared/composables/usePermissions'
import { useToast } from '@/shared/composables/useToast'
import DecisionFormDrawer from '../components/DecisionFormDrawer.vue'
import DecisionLifecycleActions from '../components/DecisionLifecycleActions.vue'
import DecisionTimeline from '../components/DecisionTimeline.vue'
import { useUpdateDecisionMutation } from '../mutations/useDecisionMutations'
import { useDecisionQuery } from '../queries/useDecisionsQuery'
import type { DecisionFormState } from '../types/decisions'
import { decisionStatusBadgeClass, validateDecisionForm } from '../validation/decisionValidation'
const { t } = useI18n(); const route = useRoute(); const router = useRouter(); const { can } = usePermissions(); const toast = useToast(); const id = computed(() => Number(route.params.id)); const { data, isLoading, isError, refetch } = useDecisionQuery(id); const decision = computed(() => data.value ?? null)
const { data: orgs } = useOrganizationUnitsFlatQuery({ status: 'active' }); const { data: employees } = useEmployeesQuery(computed(() => ({ status: 'active' as const, per_page: 100 }))); const orgOptions = computed<AppSelectOption[]>(() => [{ value: '', label: t('decisions.noOrgUnit') }, ...(orgs.value?.data ?? []).map(x => ({ value: x.id, label: x.name }))]); const employeeOptions = computed<AppSelectOption[]>(() => [{ value: '', label: t('decisions.noEmployee') }, ...(employees.value?.data ?? []).map(x => ({ value: x.id, label: x.full_name }))])
const update = useUpdateDecisionMutation(); const open = ref(false); const error = ref(''); const errors = reactive<Record<string, string>>({}); const form = reactive<DecisionFormState>({ title: '', body: '', notes: '', organization_unit_id: '', issued_by_employee_id: '', responsible_employee_id: '', effective_date: '', due_date: '' })
function edit() { if (!decision.value) return; Object.assign(form, { title: decision.value.title, body: decision.value.body, notes: decision.value.notes ?? '', organization_unit_id: decision.value.organization_unit_id ?? '', issued_by_employee_id: decision.value.issued_by_employee_id ?? '', responsible_employee_id: decision.value.responsible_employee_id ?? '', effective_date: decision.value.effective_date ?? '', due_date: decision.value.due_date ?? '' }); open.value = true }; async function save() { Object.keys(errors).forEach(x => delete errors[x]); Object.assign(errors, validateDecisionForm(form)); if (Object.keys(errors).length || !decision.value) return; await update.mutateAsync({ id: decision.value.id, payload: { ...form, organization_unit_id: form.organization_unit_id || null, issued_by_employee_id: form.issued_by_employee_id || null, responsible_employee_id: form.responsible_employee_id || null, effective_date: form.effective_date || null, due_date: form.due_date || null } }); toast.success(t('decisions.toasts.updated')); open.value = false }
</script>
<template><div class="space-y-6"><button class="rounded-lg border px-3 py-2" @click="router.push('/app/decisions')"><ArrowRight class="inline h-4 w-4" /> {{ t('decisions.backToList') }}</button><div v-if="isLoading" class="rounded-2xl border p-10 text-center">{{ t('decisions.loadingDetails') }}</div><div v-else-if="isError || !decision" class="rounded-2xl border p-10 text-center">{{ t('decisions.errors.loadDetails') }} <button @click="() => refetch()">{{ t('decisions.retry') }}</button></div><template v-else><div class="flex flex-wrap justify-between gap-4"><div><div class="flex gap-2"><span class="font-mono">{{ decision.decision_number }}</span><span class="rounded-full px-2 py-1 text-xs" :class="decisionStatusBadgeClass(decision.status)">{{ t(`decisions.status.${decision.status}`) }}</span></div><h2 class="mt-2 text-2xl font-bold">{{ decision.title }}</h2></div><PermissionGuard v-if="decision.status === 'draft' && can('decisions.update')" permission="decisions.update"><button class="rounded-xl border px-4 py-2" @click="edit"><Pencil class="inline h-4 w-4" /> {{ t('decisions.actions.edit') }}</button></PermissionGuard></div><section><h3 class="mb-3 font-bold">{{ t('decisions.sections.overview') }}</h3><div class="grid gap-4 md:grid-cols-3"><div v-for="item in [{ label: 'effectiveDate', value: decision.effective_date }, { label: 'dueDate', value: decision.due_date }, { label: 'organizationUnit', value: decision.organization_unit?.name }, { label: 'issuedBy', value: decision.issued_by_employee?.full_name }, { label: 'responsible', value: decision.responsible_employee?.full_name }]" :key="item.label" class="rounded-2xl border border-brand-border bg-brand-surface p-4"><p class="text-xs text-brand-text-muted">{{ t(`decisions.fields.${item.label}`) }}</p><p class="mt-1 font-semibold">{{ item.value ?? '—' }}</p></div></div><div class="mt-4 rounded-2xl border p-4"><p class="text-xs text-brand-text-muted">{{ t('decisions.fields.body') }}</p><p class="mt-2 whitespace-pre-wrap">{{ decision.body }}</p><p v-if="decision.notes" class="mt-3 whitespace-pre-wrap text-sm text-brand-text-secondary">{{ decision.notes }}</p></div></section><section class="rounded-2xl border p-5"><h3 class="font-bold">{{ t('decisions.sections.source') }}</h3><p v-if="!decision.source_recommendation" class="mt-2 text-sm">{{ t('decisions.standaloneSource') }}</p><template v-else><p class="mt-2">{{ decision.source_recommendation.title }}</p><RouterLink v-if="decision.source_meeting" :to="`/app/meetings/${decision.source_meeting.id}`" class="mt-2 inline-block text-sm text-brand-primary-dark underline">{{ decision.source_meeting.meeting_number }} — {{ decision.source_meeting.title }}</RouterLink></template></section><section class="rounded-2xl border p-5"><h3 class="mb-3 font-bold">{{ t('decisions.lifecycleTitle') }}</h3><DecisionLifecycleActions :decision="decision" @refreshed="() => refetch()" /></section><DecisionTimeline :transitions="decision.status_transitions ?? []" /></template><DecisionFormDrawer :open="open" :editing="decision" :form="form" :form-error="error" :field-errors="errors" :submitting="update.isPending.value" :employee-options="employeeOptions" :org-unit-options="orgOptions" @close="open = false" @submit="save" @update:form="Object.assign(form, $event)" /></div></template>
